//! The tool definitions `apps/server` advertises, one compact JSON line per tool, generated by
//! `tools/gen-tools.mjs`. `tools/list` splices the bytes unparsed; a call parses only its own
//! tool's line, to check the arguments against the advertised input schema.

use serde_json::{Map, Value};

const CATALOG: &str = include_str!("catalog.jsonl");

/// `<tool> <argument>` per line: the arguments whose schema takes `null`, so an explicit
/// `null` reaches the handler. Generated by `tools/gen-tools.mjs` from the Effect schemas.
const NULL_ARGUMENTS: &str = include_str!("null-arguments.txt");

fn keeps_null(tool: &str, argument: &str) -> bool {
    NULL_ARGUMENTS
        .lines()
        .any(|line| line.split_once(' ') == Some((tool, argument)))
}

/// Arguments whose schema the advertised JSON Schema does not show whole, so their tool
/// decodes them itself: `schedule` also takes JSON text (`OrchestratorMcpScheduleFromJsonString`).
const DECODED_BY_TOOL: [(&str, &str); 1] = [("schedule_task", "schedule")];

pub(crate) fn lines() -> impl Iterator<Item = &'static str> {
    CATALOG.lines().filter(|line| !line.is_empty())
}

/// Every tool's name, in catalog order.
#[cfg(test)]
pub(crate) fn names() -> impl Iterator<Item = &'static str> {
    lines().map(line_name).filter(|name| !name.is_empty())
}

/// The tools that act as their calling thread, one name per line, generated by
/// `tools/gen-tools.mjs` from `McpSchema.EnabledWhen = hiddenFromOutsideClients`.
const OUTSIDE_HIDDEN: &str = include_str!("outside-hidden.txt");

/// Whether a client with no calling thread is offered `tool`. As in `apps/server`, a hidden
/// tool is missing from its `tools/list` and a call to it is "not found".
pub(crate) fn offered(tool: &str, outside: bool) -> bool {
    !outside || !OUTSIDE_HIDDEN.lines().any(|name| name == tool)
}

/// The tools a delegated child is not offered (`hiddenFromSubagents`), generated by
/// `tools/gen-tools.mjs`.
const SUBAGENT_HIDDEN: &str = include_str!("subagent-hidden.txt");

/// Whether `caller` is offered `tool`: outside clients lose the calling-thread tools, and a
/// delegated child the ones its parent owns.
pub(crate) fn offered_to(tool: &str, caller: &crate::Caller) -> bool {
    match caller {
        crate::Caller::Client(_) => offered(tool, true),
        crate::Caller::Thread(thread) => {
            !thread.subagent || !SUBAGENT_HIDDEN.lines().any(|name| name == tool)
        }
    }
}

pub(crate) fn line_name(line: &str) -> &str {
    line.strip_prefix("{\"name\":\"")
        .and_then(|rest| rest.split_once('"'))
        .map_or("", |(name, _)| name)
}

/// The `tools/list` result body, for a caller in a thread or an outside client.
#[cfg(test)]
pub(crate) fn list_result(outside: bool) -> String {
    list_filtered(|name| offered(name, outside) && name != "tool_search")
}

/// The `tools/list` result body for `caller`.
pub(crate) fn list_for(caller: &crate::Caller) -> String {
    list_filtered(|name| offered_to(name, caller) && name != "tool_search")
}

pub(crate) fn list_filtered(visible: impl Fn(&str) -> bool) -> String {
    let mut out = String::with_capacity(CATALOG.len() + 16);
    out.push_str("{\"tools\":[");
    let offered = lines().filter(|line| visible(line_name(line)));
    for (i, line) in offered.enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(line);
    }
    out.push_str("]}");
    out
}

/// One tool's definition, parsed, and its argument names in advertised order (serde_json
/// sorts object keys; error texts list them as TS does).
pub(crate) fn tool(name: &str) -> Option<(Value, Vec<String>)> {
    let line = line(name)?;
    let tool = serde_json::from_str(line).ok()?;
    Some((tool, argument_order(line)))
}

/// One tool's catalog line, unparsed: its keys keep the contract's order.
pub(crate) fn line(name: &str) -> Option<&'static str> {
    let prefix = format!("{{\"name\":{},", Value::String(name.to_owned()));
    lines().find(|line| line.starts_with(&prefix))
}

/// The keys of `inputSchema.properties`, as written in the line.
fn argument_order(line: &str) -> Vec<String> {
    const START: &str = "\"inputSchema\":{\"type\":\"object\",\"properties\":{";
    let Some(at) = line.find(START) else {
        return Vec::new();
    };
    let mut keys = Vec::new();
    let mut depth = 0usize;
    let mut chars = line[at + START.len()..].char_indices().peekable();
    let rest = &line[at + START.len()..];
    while let Some((i, c)) = chars.next() {
        match c {
            '"' => {
                let start = i + 1;
                let mut end = start;
                while let Some((j, c)) = chars.next() {
                    if c == '\\' {
                        chars.next();
                    } else if c == '"' {
                        end = j;
                        break;
                    }
                }
                let is_key = depth == 0 && chars.peek().is_some_and(|(_, c)| *c == ':');
                if is_key
                    && let Ok(Value::String(key)) =
                        serde_json::from_str(rest.get(start - 1..=end).unwrap_or_default())
                {
                    keys.push(key);
                }
            }
            '{' | '[' => depth += 1,
            '}' | ']' if depth == 0 => break,
            '}' | ']' => depth -= 1,
            _ => {}
        }
    }
    keys
}

const MAX_NAMED_ARGUMENTS: usize = 5;

/// Checks `arguments` as `decodeAsAdvertised` does in TS: `null` for an optional field counts
/// as omitted (and is removed) unless the field takes `null` ([`NULL_ARGUMENTS`]), an argument the schema does not list is refused by name, and
/// required fields and simple types are checked. Nested objects stay lenient, as in TS.
/// The error text follows Effect's where an agent relies on it (unknown and missing keys).
pub(crate) fn check_arguments(
    name: &str,
    schema: &Value,
    order: &[String],
    arguments: &mut Map<String, Value>,
) -> Result<(), String> {
    let empty = Map::new();
    let properties = schema["properties"].as_object().unwrap_or(&empty);
    let required: Vec<&str> = schema["required"]
        .as_array()
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let unknown: Vec<&String> = arguments
        .keys()
        .filter(|key| !properties.contains_key(*key))
        .collect();
    if !unknown.is_empty() {
        let named: Vec<String> = unknown
            .iter()
            .take(MAX_NAMED_ARGUMENTS)
            .map(|key| Value::String(key.chars().take(64).collect()).to_string())
            .collect();
        let more = if unknown.len() > named.len() {
            format!(" and {} more", unknown.len() - named.len())
        } else {
            String::new()
        };
        let accepted = if properties.is_empty() {
            "none".to_owned()
        } else {
            order.join(", ")
        };
        return Err(format!(
            "Unknown argument{} {}{more}. Accepted arguments: {accepted}.",
            if unknown.len() == 1 { "" } else { "s" },
            named.join(", ")
        ));
    }
    arguments.retain(|key, value| {
        !value.is_null() || required.contains(&key.as_str()) || keeps_null(name, key)
    });
    for key in &required {
        if !arguments.contains_key(*key) {
            return Err(format!("Missing key\n  at [\"{key}\"]"));
        }
    }
    for (key, value) in arguments.iter() {
        if value.is_null() && keeps_null(name, key)
            || DECODED_BY_TOOL.contains(&(name, key.as_str()))
        {
            continue;
        }
        let optional = !required.contains(&key.as_str());
        // An array's elements decode before its own checks, each at its index.
        if let (Some(item), Some(items)) = (properties[key].get("items"), value.as_array()) {
            for (index, element) in items.iter().enumerate() {
                if let Some(problem) = type_problem(item, element, false) {
                    return Err(format!("{problem}\n  at [\"{key}\"][{index}]"));
                }
                // An element that is an object decodes its own fields, each at its key.
                if let (Some(fields), Some(element)) =
                    (item["properties"].as_object(), element.as_object())
                {
                    let inner: Vec<&str> = item["required"]
                        .as_array()
                        .map(|r| r.iter().filter_map(Value::as_str).collect())
                        .unwrap_or_default();
                    for (field, field_value) in element {
                        // `null` stays the element's own decoder's to judge, as before.
                        let Some(field_schema) =
                            fields.get(field).filter(|_| !field_value.is_null())
                        else {
                            continue;
                        };
                        let optional = !inner.contains(&field.as_str());
                        if let Some(problem) = type_problem(field_schema, field_value, optional) {
                            return Err(format!(
                                "{problem}\n  at [\"{key}\"][{index}][{}]",
                                Value::String(field.clone())
                            ));
                        }
                    }
                }
            }
        }
        if let Some(problem) = type_problem(&properties[key], value, optional) {
            return Err(format!("{problem}\n  at [\"{key}\"]"));
        }
    }
    Ok(())
}

/// Effect's decode texts. A value of the wrong JSON type reads `Expected <type>`, with
/// ` | null` for an optional field (its JSON codec also takes `null`); integers are `number`.
fn type_problem(schema: &Value, value: &Value, optional: bool) -> Option<String> {
    let or_null = if optional { " | null" } else { "" };
    if let Some(options) = schema["anyOf"].as_array() {
        return options
            .iter()
            .all(|option| type_problem(option, value, false).is_some())
            .then(|| format!("Expected a value matching the schema, got {value}"));
    }
    if let Some(allowed) = schema["enum"].as_array()
        && !allowed.contains(value)
    {
        let names: Vec<String> = allowed.iter().map(Value::to_string).collect();
        // A string outside the literals fails on the literals alone; any other type also
        // fails the codec's `null` branch.
        let suffix = if value.is_string() { "" } else { or_null };
        return Some(format!("Expected {}{suffix}", names.join(" | ")));
    }
    let kind = schema["type"].as_str();
    let fits = match kind {
        Some("string") => value.is_string(),
        Some("integer" | "number") => value.is_number(),
        Some("boolean") => value.is_boolean(),
        Some("array") => value.is_array(),
        Some("object") => value.is_object(),
        _ => true,
    };
    if !fits {
        let kind = match kind {
            Some("integer") => "number",
            Some(other) => other,
            None => "unknown",
        };
        return Some(format!("Expected {kind}{or_null}"));
    }
    match value {
        Value::String(text) => length_problem(schema, text),
        Value::Number(number) => {
            let n = number.as_f64().unwrap_or(f64::NAN);
            if kind == Some("integer") && n.fract() != 0.0 {
                return Some("Expected an integer".to_owned());
            }
            range_problem(schema, n)
        }
        Value::Array(items) => {
            let length = items.len() as u64;
            if let Some(min) = schema["minItems"].as_u64().filter(|min| length < *min) {
                return Some(format!("Expected a value with a length of at least {min}"));
            }
            schema["maxItems"]
                .as_u64()
                .filter(|max| length > *max)
                .map(|max| format!("Expected a value with a length of at most {max}"))
        }
        _ => None,
    }
}

/// Effect's `isMinLength` and `isMaxLength`: a JavaScript string's length, in UTF-16 units.
fn length_problem(schema: &Value, text: &str) -> Option<String> {
    let length = text.encode_utf16().count() as u64;
    if let Some(min) = schema["minLength"].as_u64()
        && length < min
    {
        return Some(format!("Expected a value with a length of at least {min}"));
    }
    if let Some(max) = schema["maxLength"].as_u64()
        && length > max
    {
        return Some(format!("Expected a value with a length of at most {max}"));
    }
    None
}

/// Effect's `isBetween`, `isGreaterThanOrEqualTo` and `isLessThanOrEqualTo` texts.
fn range_problem(schema: &Value, n: f64) -> Option<String> {
    let (min, max) = (&schema["minimum"], &schema["maximum"]);
    let below = min.as_f64().is_some_and(|min| n < min);
    let above = max.as_f64().is_some_and(|max| n > max);
    if !below && !above {
        return None;
    }
    Some(match (min.is_number(), max.is_number()) {
        (true, true) => format!("Expected a value between {min} and {max}"),
        (true, false) => format!("Expected a value greater than or equal to {min}"),
        _ => format!("Expected a value less than or equal to {max}"),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn every_line_parses_and_names_itself() {
        for line in lines() {
            let tool: Value = serde_json::from_str(line).unwrap();
            assert_eq!(tool["inputSchema"]["type"], "object");
            assert!(names().any(|n| n == tool["name"]));
        }
        let list: Value = serde_json::from_str(&list_result(false)).unwrap();
        assert_eq!(
            list["tools"].as_array().unwrap().len(),
            names().filter(|name| *name != "tool_search").count()
        );
    }

    /// The catalog is byte for byte what a live TypeScript server listed
    /// (`fixtures/ts-tools-list.json`, a real `tools/list` reply).
    #[test]
    fn matches_the_typescript_servers_tools_list() {
        let dump: Value =
            serde_json::from_str(include_str!("../fixtures/ts-tools-list.json")).unwrap();
        let live = dump["result"]["tools"].as_array().unwrap();
        for line in lines() {
            let ours: Value = serde_json::from_str(line).unwrap();
            // The dump is an outside client's list: the tools that act as a thread are missing.
            if !offered(line_name(line), true) {
                assert!(live.iter().all(|t| t["name"] != ours["name"]));
                continue;
            }
            let theirs = live
                .iter()
                .find(|t| t["name"] == ours["name"])
                .unwrap_or_else(|| panic!("{} is not in the TS dump", ours["name"]));
            assert_eq!(&ours, theirs, "{}", ours["name"]);
        }
    }

    #[test]
    fn checks_arguments_like_the_typescript_decoder() {
        let (list, order) = tool("t3_thread_list").unwrap();
        let schema = list["inputSchema"].clone();
        let mut args = json!({"bogus": 1}).as_object().unwrap().clone();
        assert_eq!(
            check_arguments("t3_thread_list", &schema, &order, &mut args).unwrap_err(),
            "Unknown argument \"bogus\". Accepted arguments: environmentId, projectId, allProjects, statuses, titleContains, settled, snoozed, includeSubagents, cursor, limit."
        );
        let (wait, wait_order) = tool("t3_thread_wait").unwrap();
        let wait = wait["inputSchema"].clone();
        let mut args = Map::new();
        assert_eq!(
            check_arguments("t3_thread_wait", &wait, &wait_order, &mut args).unwrap_err(),
            "Missing key\n  at [\"threadId\"]"
        );
        let mut args = json!({"threadId": "t", "runId": null})
            .as_object()
            .unwrap()
            .clone();
        check_arguments("t3_thread_wait", &wait, &wait_order, &mut args).unwrap();
        assert!(!args.contains_key("runId"));
        let mut args = json!({"threadId": 5}).as_object().unwrap().clone();
        assert!(check_arguments("t3_thread_wait", &wait, &wait_order, &mut args).is_err());
        // T3 #30976: a limit above the maximum passes, and the tool clamps it.
        let mut args = json!({"limit": 101}).as_object().unwrap().clone();
        check_arguments("t3_thread_list", &schema, &order, &mut args).unwrap();
        let mut args = json!({"limit": 0}).as_object().unwrap().clone();
        assert!(check_arguments("t3_thread_list", &schema, &order, &mut args).is_err());
        let mut args = json!({"statuses": ["running"]})
            .as_object()
            .unwrap()
            .clone();
        check_arguments("t3_thread_list", &schema, &order, &mut args).unwrap();
        // String lengths count UTF-16 units, as a JavaScript string's length.
        let (send, send_order) = tool("send_to_user").unwrap();
        let send = send["inputSchema"].clone();
        for (text, problem) in [
            (
                String::new(),
                Some("Expected a value with a length of at least 1"),
            ),
            ("漢".repeat(4_000), None),
            ("😀".repeat(2_000), None),
            (
                "😀".repeat(2_001),
                Some("Expected a value with a length of at most 4000"),
            ),
        ] {
            let mut args = json!({"message": text}).as_object().unwrap().clone();
            assert_eq!(
                check_arguments("send_to_user", &send, &send_order, &mut args).err(),
                problem.map(|p| format!("{p}\n  at [\"message\"]"))
            );
        }
        // Integer bounds read as Effect's; `null` stays only where the schema takes it.
        let (queue, queue_order) = tool("t3_queue").unwrap();
        let queue = queue["inputSchema"].clone();
        for (args, problem) in [
            (
                json!({"action": "list", "limit": 0}),
                // `clampedPositiveInt(100)` since T3 #30976: only the lower bound refuses.
                Some("Expected a value greater than or equal to 1\n  at [\"limit\"]"),
            ),
            (
                json!({"action": "list", "cursor": -1}),
                Some("Expected a value greater than or equal to 0\n  at [\"cursor\"]"),
            ),
            (
                json!({"action": "list", "limit": 1.5}),
                Some("Expected an integer\n  at [\"limit\"]"),
            ),
            (json!({"action": "reorder", "beforeRunId": null}), None),
        ] {
            let mut args = args.as_object().unwrap().clone();
            assert_eq!(
                check_arguments("t3_queue", &queue, &queue_order, &mut args).err(),
                problem.map(str::to_owned)
            );
        }
        let mut args = json!({"action": "reorder", "beforeRunId": null, "queuedRunId": null})
            .as_object()
            .unwrap()
            .clone();
        check_arguments("t3_queue", &queue, &queue_order, &mut args).unwrap();
        assert_eq!(args.get("beforeRunId"), Some(&Value::Null));
        assert!(!args.contains_key("queuedRunId"));
    }
}
